 rows=[[2,5,2],[4,2,2],[1,4,4],[a4,3-a4,5],[3,e5,5-e5],[1,1,1]]
 sums=[sum(row[j] for row in rows) for j in range(3)]
 if sums[1]>sums[2]:awards.append(dict(rows=rows,sums=sums))
